mc.shareStats=nil
end
if mc.autoTeamChosen~=true then
mc.autoTeam=nil
end
for nc,oc in pairs(N.DEFAULTS)do
if mc[nc]~=nil and type(mc[nc])==type(oc)then
O[nc]=mc[nc]
else
O[nc]=oc
end
end
O.seenVersion=type(mc.seenVersion)==iee[859]and mc.seenVersion or nil
if mc.griffinWatch==true and mc.snipeUnit==nil then
O.snipeOn,O.snipeUnit=true,iee[1032]
end
if O.pickPortal==iee[877]then
O.portals,O.pickPortal=false,iee[874]
end
if O.huntCards==iee[1961]then
O.huntCards=iee[1962]
end
O.cfgv=1
if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
end
O.play=true
for pc,qc in ipairs({iee[1963],iee[1964],iee[1965],iee[1966],iee[1967],iee[1968],iee[1969],iee[1970]})do
O[qc]=true
end
end
end
