function hb.pullGoal()
local pX=O.pullGoal
if type(pX)~=iee[859]or pX==iee[873]or type(N.Units[pX])~=iee[1950]then
return nil
end
local qX=N.prof()
if not qX then
return nil
end
local rX=N.Units[pX]
local sX=rX.evolve and rX.evolve.evolve_unit or pX
local tX={id=pX,to=sX,coins=N.cur(iee[2840]),itemCost=0,needCoins=0}
for uX,vX in pairs(rX.evolve and rX.evolve.normal and rX.evolve.normal.item_requirement or{})do
local wX=N.SaleEvent[vX.item_id]
if wX and type(wX.resource_cost)==iee[1950]and wX.resource_cost.id==iee[2840]then
tX.item,tX.itemCost=vX.item_id,tonumber(wX.resource_cost.amount)or 0
end
end
tX.haveItem=tX.item~=nil and hb.have(tX.item)>0
local xX,yX=ab.hatched[pX]or false,false
for zX,AX in pairs(qX.collection.owned_units)do
if AX.unit_id==pX then
xX=true
end
if AX.unit_id==sX then
yX=true
end
end
if yX then
tX.step=iee[2841]
elseif not xX then
tX.step,tX.needCoins=iee[2842],1
elseif tX.item and not tX.haveItem then
tX.step,tX.needCoins=iee[2813],math.max(0,tX.itemCost-tX.coins)
else
tX.step=iee[2046]
end
return tX
end
