local GX=FX and tonumber(FX.opens_since_mythic)
return DX..string.format(iee[2847]..iee[2848]..iee[2849],V.name(BX.id),U.fmt(BX.coins),math.max(0,math.floor((BX.coins-EX)/1500)),U.fmt(EX),V.name(BX.id),GX and string.format(iee[2850],GX)or iee[873],math.max(O.aprilValue,O.goalCoinValue),O.summonApril and iee[2851]or iee[2852])
elseif BX.step==iee[2813]then
return DX..string.format(iee[2853],V.name(BX.id),U.fmt(BX.itemCost),U.fmt(BX.coins))
elseif BX.step==iee[2046]then
return DX..iee[2854]
end
return DX..iee[2855]
end
function ab.eventShop()
