if not(O.summonApril and HX and HX.step==iee[2813]and HX.coins>=HX.itemCost and HX.itemCost>0)then
return
end
if F.req.back.eshop and U.now()<F.req.back.eshop then
return
end
local IX,JX=F.request(iee[2856],iee[2553],HX.item,iee[1967],iee[2554],iee[2389])
local KX=U.now()
while U.now()-KX<4 and hb.have(HX.item)<1 do
task.wait(0.25)
end
local LX=(N.Items[HX.item]or{}).name or HX.item
if hb.have(HX.item)>0 then
cb.add(LX,HX.itemCost,iee[2840],iee[2857]..V.name(HX.to))
if F.notify then
F.notify(iee[71],iee[2858]..LX..iee[2859]..V.name(HX.id),iee[2860])
end
pcall(hb.refresh)
else
F.log(1,iee[2861],iee[2862]..tostring(HX.item)..iee[2632]..tostring(IX and JX or iee[2536])..iee[2604])
F.backoff(iee[2856],900)
end
