return
end
local NX=MX.redeemed_codes or{}
local OX,PX={},{}
for QX,RX in ipairs(N.CODES)do
local SX=tonumber(P.codes[RX])
if NX[RX]then
if SX and SX>0 then
table.insert(PX,RX)
P.codes[RX]= -1
end
elseif os.time()-(SX or 0)>86400 and(SX or 0)>=0 then
P.codes[RX]=os.time()
local TX=F.request(iee[2864],iee[2865],RX)
if TX then
table.insert(OX,RX)
end
task.wait(1)
end
end
if#PX>0 then
F.log(1,iee[2866],iee[2867]..table.concat(PX,iee[2062]))
pcall(F.feed,iee[2591],iee[2868],table.concat(PX,iee[2062]))
