if#OX>0 then
F.log(1,iee[2866],iee[2869]..table.concat(OX,iee[2062])..iee[2870])
end
F.saveSoon()
local UX=0
for VX,WX in ipairs(N.CODES)do
if not NX[WX]then
UX=UX+1
end
end
F.status(iee[99],#OX>0 and(iee[2869]..table.concat(OX,iee[2062]))or(UX==0 and iee[2871]or(UX..iee[2872])))
end
