return{item=pY,done=true}
end
local sY=hb.sources()[pY]
if sY and sY[1]then
return{item=pY,need=qY,have=rY,farm=pY,farmNeed=qY-rY,levels=sY}
end
local tY=N.SaleEvent[pY]
if tY and type(tY.resource_cost)==iee[1950]then
