local wY=hb.sources()[vY.costItem]
local xY=vY.cost*(qY-rY)
local yY=hb.have(vY.costItem)
return{item=pY,need=qY,have=rY,shopKey=uY,costItem=vY.costItem,cost=vY.cost,farm=vY.costItem,farmNeed=math.max(0,xY-yY),levels=wY or{}}
end
end
for zY,AY in pairs(W.PORTALS)do
if AY.item==pY then
return{item=pY,need=qY,have=rY,farm=pY,farmNeed=qY-rY,portal=zY,levels={{level=AY.level,per=W.portalPer(zY)}}}
