if w4 .magic then
y4=0
else
y4=y4+(tonumber(H4 .dmg_buff)or 0)*0.3
end
elseif G4 .id==iee[2931]then
if w4 .water_damage then
y4=y4+0.05
end
elseif G4 .id==iee[2084]then
local L4=tonumber(H4 .duration_buff)or tonumber(type(G4 .static_params)==iee[1950]and G4 .static_params.duration_buff)or 2
local M4,N4=pcall(V.attackInfo,D4 and D4 .atk,D4 and D4 .range)
