ab.WORLD_SKIP_RETRY=3600
ab.LOBBY_EVERY=6*3600
function ab.worldSkip()
if F.where~=iee[2021]or not O.worldSkip or not(O.firstClears or O.onlyStory)then
return
end
local Ymb=N.WLO and N.WLO.SKIPPABLE_WORLDS
if type(Ymb)~=iee[1950]then
return
end
local Zmb=(N.prof()or{}).level_data or{}
local _mb,anb,bnb
for cnb,dnb in ipairs(U.list(N.WLO.WORLD_ORDER))do
local enb=N.Worlds[dnb]
if enb and not enb.legend_stage and not enb.raid_world then
local fnb=U.list(enb.levels)
local gnb=fnb[#fnb]
if gnb and not W.done(Zmb,gnb.id,iee[2392])then
_mb,anb,bnb=dnb,fnb[1],gnb
break
end
end
end
if not(_mb and Ymb[_mb]and anb and bnb)then
return
end
if W.open(bnb.id)or not W.open(anb.id)then
return
end
P.worldSkip=type(P.worldSkip)==iee[1950]and P.worldSkip or{}
local hnb=P.worldSkip[_mb]
if type(hnb)==iee[1950]and(hnb.done or os.time()-(tonumber(hnb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local inb=N.Worlds[_mb]
local jnb=tostring(inb and inb.name or _mb)
local knb={key=iee[2631]..bnb.id..iee[2736],kind=iee[1989],first=true,level=bnb.id,diff=iee[2392],label=W.levelName(bnb.id)..iee[2737]}
local lnb,mnb=pcall(gb.plan,knb,false)
if not(lnb and type(mnb)==iee[1950])then
return
end
if not mnb.won then
if ab.every(iee[3303].._mb,3600)then
F.log(1,iee[2565],string.format(iee[3304],jnb,W.levelName(bnb.id),tostring(mnb.margin)))
end
return
end
local nnb={}
for onb,pnb in ipairs(U.list(inb.levels))do
nnb[pnb.id]=W.done(Zmb,pnb.id,iee[2392])
end
local qnb=U.now()
F.log(1,iee[2565],string.format(iee[3305],jnb,W.levelName(bnb.id),tostring(mnb.margin)))
local rnb,snb=F.request(iee[3306],iee[3307],_mb)
local tnb=false
while U.now()-qnb<8 do
task.wait(1)
if W.open(bnb.id)then
tnb=true
break
end
end
local unb=F.gameSaid(qnb)
P.worldSkip[_mb]={at=os.time(),done=tnb or nil,last=bnb.id,said=unb and tostring(unb):sub(1,80)or nil}
F.saveSoon()
if tnb then
local vnb=(N.prof()or{}).level_data or{}
local wnb={}
for xnb,ynb in ipairs(U.list(inb.levels))do
if ynb.id~=bnb.id and not nnb[ynb.id]and W.done(vnb,ynb.id,iee[2392])then
table.insert(wnb,W.levelName(ynb.id))
end
end
F.log(1,iee[2565],string.format(iee[3308],jnb,#wnb>0 and(iee[3309]..table.concat(wnb,iee[2062]))or iee[3310],unb and(iee[3311]..tostring(unb))or iee[873]))
W.lastScored=nil
else
F.log(1,iee[2565],string.format(iee[3312],jnb,tostring(unb or(rnb and snb)or iee[2536])))
end
end
function ab.icLaunch(znb)
