return
end
local uob= #game:GetService(iee[852]):GetPlayers()>1 or bb.withOthers
local vob=tonumber(bb.enemyHpSum)or 0
if not uob or vob<=0 then
return
end
local wob,xob=pcall(ab.partyOnly)
if wob and xob then
return
end
local yob,zob,Aob=pcall(bb.damageShares)
local Bob=yob and tonumber(Aob)or 0
local Cob=math.min(1,Bob/vob)
bb.mmShareNow=Cob
P.mmShare=type(P.mmShare)==iee[1950]and P.mmShare or{}
P.mmShare[tob]={share=Cob,at=os.time(),wave=bb.wave(),players= #game:GetService(iee[852]):GetPlayers()}
if Cob<ab.MM_MIN_SHARE and O.mmGuard==false then
F.log(1,iee[2611],string.format(iee[3354],Cob*100,math.floor(ab.MM_MIN_SHARE*100+0.5)))
elseif Cob<ab.MM_MIN_SHARE then
F.log(1,iee[2611],string.format(iee[3355],Cob*100,math.floor(ab.MM_MIN_SHARE*100+0.5)))
else
F.log(2,iee[2611],string.format(iee[3356],Cob*100))
end
F.saveSoon()
end
function ab.mmTooWeak(Dob)
