return type(Eob)==iee[1950]and(tonumber(Eob.share)or 1)<ab.MM_MIN_SHARE and os.time()-(tonumber(Eob.at)or 0)<ab.MM_REST
end
function ab.mmGuardLines()
local Fob={}
if O.mmGuard==false or type(P.mmShare)~=iee[1950]then
return Fob
end
for Gob,Hob in pairs(P.mmShare)do
local Iob=type(Hob)==iee[1950]and(tonumber(Hob.share)or 1)<ab.MM_MIN_SHARE and ab.MM_REST-(os.time()-(tonumber(Hob.at)or 0))or 0
if Iob>0 then
local Job,Kob=pcall(nb.keyName,Gob)
table.insert(Fob,string.format(iee[3357],Job and Kob or tostring(Gob),ab.leftWords(Iob),(tonumber(Hob.share)or 0)*100))
end
end
table.sort(Fob)
