function ab.matchSwitch(Lob)
if P.trial or(P.testTeam and(P.testTeam.left or 0)>0)then
return false
end
if Lob.kind==iee[2400]then
return O.dailyMatch==true
end
local Mob=(Lob.kind==iee[1990]and O.mmRaid)or(Lob.kind==iee[1969]and O.mmInfinite)or(Lob.kind==iee[1989]and Lob.legend and O.mmLegend)or(Lob.kind==iee[1967]and O.mmEvent)
local Nob=Mob and N.Levels[Lob.level]
return Nob~=nil and Nob~=false and type(Nob._MATCHMAKING)==iee[1950]
end
function ab.matchWant(Oob)
if not ab.matchSwitch(Oob)then
return false
end
if Oob.kind~=iee[2400]and ab.mmTooWeak(Oob)then
