return Rob>0 and Rob or nil
end
function ab.leftWords(Sob)
Sob=math.max(0,math.floor(tonumber(Sob)or 0))
local Tob,Uob=math.floor(Sob/3600),math.ceil((Sob%3600)/60)
if Uob==60 then
Tob,Uob=Tob+1,0
end
return Tob>0 and string.format(iee[3358],Tob,Uob)or string.format(iee[2598],Uob)
end
function ab.mmNote(Vob,Wob,Xob,Yob)
