function ab.unitLab(Osb)
if not ab.unitLabSafe(Osb)then
return
end
P.unitLab=type(P.unitLab)==iee[1950]and P.unitLab or{}
local Psb=P.unitLab
Psb.tried=type(Psb.tried)==iee[1950]and Psb.tried or{}
Psb.seen=(tonumber(Psb.seen)or 0)+1
if Psb.seen%ab.LAB.EVERY~=0 then
return
end
local Qsb=N.session()
local Rsb=V.equipped()
if not Qsb or#Rsb<2 then
return
end
local Ssb={}
for Tsb,Usb in ipairs(Rsb)do
Ssb[Usb.uuid]=true
Ssb[Usb.id]=true
end
local Vsb,Wsb,Xsb
for Ysb,Zsb in pairs(Qsb.profile_data.collection.owned_units)do
local _sb=Zsb.unit_id
if not Ssb[Ysb]and not Ssb[_sb]and N.Units[_sb]and not V.isFarm(_sb)and not V.allyBuff(_sb)and os.time()-(tonumber(Psb.tried[_sb])or 0)>ab.LAB.AGAIN then
local atb=ab.unitEvidence(_sb)
if atb<ab.LAB.MIN_EVIDENCE then
local btb=Qsb.collection:get_unit_by_uuid(Ysb)or Zsb
local ctb=kb.score(btb)
if ctb>0 and(not Vsb or atb<Wsb or(atb==Wsb and ctb>Xsb))then
Vsb,Wsb,Xsb={uuid=Ysb,id=_sb,u=btb},atb,ctb
end
end
end
end
if not Vsb then
return
end
local dtb,etb
for ftb,gtb in ipairs(Rsb)do
if not V.isFarm(gtb.id)and not V.allyBuff(gtb.id)and gtb.uuid~=O.evolveUnit then
local htb=kb.score(gtb.u)
if not dtb or htb<etb then
dtb,etb=gtb,htb
end
end
end
if not dtb then
return
end
Psb.tried[Vsb.id]=os.time()
local itb=0
for jtb in pairs(Psb.tried)do
itb=itb+1
if itb>300 then
Psb.tried[jtb]=nil
end
end
local ktb,ltb=gb.levelFor(Osb)
