local ntb={}
for otb,ptb in ipairs(Rsb)do
table.insert(ntb,ptb.uuid==dtb.uuid and Vsb.u or ptb.u)
end
local qtb,rtb=pcall(gb.run,mtb,gb.teamFrom(ntb,mtb.map),{hpMul=1.1})
local stb=qtb and type(rtb)==iee[1950]and(rtb.won or(mtb.infinite and(tonumber(rtb.wave)or 0)>=0.8*W.infReach(Osb.key)))
if not stb then
F.log(2,iee[3442],string.format(iee[3443],V.name(Vsb.id),Osb.label))
return
end
local ttb={}
for utb,vtb in ipairs(Rsb)do
table.insert(ttb,vtb.uuid==dtb.uuid and Vsb.uuid or vtb.uuid)
end
if ab.equipTeam(ttb,iee[3444]..V.name(Vsb.id))then
Psb.now={id=Vsb.id,out=dtb.id,key=Osb.key,at=os.time(),ev=Wsb}
