local Vfc,Wfc,Xfc=jb.res(jb.data())
if Wfc+Xfc<=0 or Rfc>=2 then
break
end
local Yfc,Zfc
if Wfc>0 then
Yfc,Zfc=F.request(iee[3871],iee[3872])
else
