jb.note(string.format(iee[3875],Pfc,Qfc,Jfc and iee[3876]or(Nfc<=1 and iee[3877]or iee[3878]),jb.luck(Ifc),(tonumber(N.cur(iee[2014]))or 0)-Sfc))
local lgc,mgc,ngc=jb.res(jb.data())
if(Jfc or Ofc>=jb.ROOMS)and mgc+ngc>0 then
jb.note(string.format(iee[3879],mgc,ngc))
W.rec(iee[2661]).restUntil=os.time()+1800
return iee[3880]
