function jb.forced(zgc)
local Agc=P.dg.force
if type(Agc)~=iee[1950]or type(Agc.uuids)~=iee[1950]or Agc.seed~=tostring(zgc.r._r)then
return nil
end
if os.time()-(tonumber(Agc.at)or 0)>3600 then
P.dg.force=nil
return nil
end
return Agc
end
function jb.startTeam(Bgc,Cgc,Dgc,Egc)
P.startTeam={uuids=table.clone(Bgc),must=true,own=Egc or nil,seed=tostring(Cgc.r._r),why=Dgc}
end
function jb.planTeam(Fgc,Ggc,Hgc)
if not(O.sim and O.simTeams)or type(Fgc.r._l)~=iee[1950]then
return
end
if jb.playLast()then
F.log(1,iee[3586],string.format(iee[3891],Fgc.d))
return
end
local Igc=jb.forced(Fgc)
if Igc then
if Hgc then
F.log(1,iee[3586],string.format(iee[3892],Fgc.d,tostring(Igc.label)))
if not ib.same(ib.team(),Igc.uuids)then
jb.startTeam(Igc.uuids,Fgc,tostring(Igc.label))
end
return
end
F.log(1,iee[3586],string.format(iee[3893],Fgc.d,tostring(Igc.label)))
ab.equipTeam(Igc.uuids,tostring(Igc.label))
task.wait(0.5)
return
end
if Hgc and not O.autoTeam then
return
end
local Jgc=P.simTeam.dg
if not Hgc and O.autoTeam and Jgc and Jgc.better and not Jgc.stale and Jgc.seed==tostring(Fgc.r._r)and os.time()-(tonumber(Jgc.at)or 0)<300 then
ab.equipTeam(Jgc.uuids,iee[3894]..Fgc.d)
task.wait(0.5)
return
end
local Kgc=jb.fx(Ggc,jb.roomCurse(Fgc.r))
local Lgc={}
if Hgc and type(P.savedTeam)==iee[1950]and#P.savedTeam>0 then
local Mgc=N.session()
for Ngc,Ogc in ipairs(P.savedTeam)do
local Pgc=Mgc.collection:get_unit_by_uuid(Ogc)
if Pgc then
table.insert(Lgc,Pgc)
end
end
else
for Qgc,Rgc in ipairs(V.equipped())do
table.insert(Lgc,Rgc.u)
end
end
if#Lgc==0 then
return
end
local Sgc=jb.mod(Fgc.r._l)
local Tgc=gb.applyFx(gb.info(gb.slim(Fgc.r._l),iee[2661],nil,Sgc),Kgc)
local Ugc=jb.applyK(Tgc,Fgc.r._r)
if Ugc>1 then
F.log(1,iee[3586],string.format(iee[3895],Fgc.d,Ugc))
end
F.status(iee[2980],iee[3896]..Fgc.d)
gb.memoOn()
local Vgc=jb.ways(Tgc)
local Wgc=type(P.dg.styles)==iee[1950]and P.dg.styles[tostring(Fgc.r._r)]or nil
local function Xgc(Ygc,Zgc)
local _gc=gb.sig(Ygc)
local ahc=type(P.dg.teams)==iee[1950]and P.dg.teams[_gc]or{}
local bhc=type(P.dg.lost)==iee[1950]and P.dg.lost[tostring(Fgc.r._r)]and P.dg.lost[tostring(Fgc.r._r)][_gc]or 0
local chc=type(P.dg.bailed)==iee[1950]and type(P.dg.bailed[tostring(Fgc.r._r)])==iee[1950]and tonumber(P.dg.bailed[tostring(Fgc.r._r)][_gc])or 0
bhc=bhc+chc
local dhc,ehc,fhc,ghc=gb.strength(Zgc.info,Ygc)
local hhc=math.clamp((tonumber(ahc.w)or 0)-2*(tonumber(ahc.l)or 0),-6,3)
if Fgc.d>=13 then
hhc=math.min(hhc,1)
end
hhc=hhc-3*bhc
local ihc=Wgc and type(Wgc.lost)==iee[1950]and Wgc.lost[Zgc.style]or nil
if type(ihc)==iee[1950]and ihc.sig==_gc then
hhc=hhc-3
end
return{score=dhc+hhc,wins=dhc,atOne=ehc,reach=fhc,far=ghc,lostHere=bhc,left=chc,w=tonumber(ahc.w)or 0,l=tonumber(ahc.l)or 0,style=Zgc.style}
end
local function jhc(khc)
for lhc,mhc in ipairs(Vgc)do
if mhc.style==khc then
return mhc
end
end
return Vgc[2]
end
local function nhc(ohc,phc)
return not phc or ohc.score>phc.score or(ohc.score==phc.score and(ohc.far or 0)>(phc.far or 0))
end
local function qhc(rhc)
local shc
for thc,uhc in ipairs(Vgc)do
local vhc=Xgc(rhc,uhc)
if nhc(vhc,shc)then
shc=vhc
end
task.wait()
end
return shc
end
local whc=qhc(Lgc)
if whc.wins>=3* #gb.LADDER and whc.lostHere==0 then
gb.memo=nil
local xhc,yhc={},{}
for zhc,Ahc in ipairs(Lgc)do
table.insert(xhc,Ahc.uuid)
table.insert(yhc,V.name(Ahc.unit_id))
end
P.simTeam.dg={uuids=xhc,names=yhc,won=true,wave=Tgc.total,better=false,cur={won=true,wave=Tgc.total},at=os.time(),label=iee[3897],seed=tostring(Fgc.r._r),style=whc.style}
F.log(1,iee[3586],string.format(iee[3898],Fgc.d,gb.LADDER[#gb.LADDER],whc.w,whc.l))
pcall(function()
local Bhc,Chc=pcall(jb.roomName,Fgc)
gb.explainSave(iee[2661],string.format(iee[3899],Fgc.d,Bhc and tostring(Chc)or iee[2185]),Tgc,Lgc,{string.format(iee[3900],gb.LADDER[#gb.LADDER],whc.w,whc.l)},false,Lgc,{won=true,wave=Tgc.total,total=Tgc.total,steps=whc.wins,mySteps=whc.wins,realW=whc.w,realL=whc.l})
end)
if Hgc and type(P.savedTeam)==iee[1950]and not ib.same(ib.team(),P.savedTeam)then
jb.startTeam(P.savedTeam,Fgc,iee[3901]..Fgc.d,true)
end
return
end
local Dhc=gb.pool(Sgc,Tgc)
local Ehc=(jb.lives(Ggc)<=1 and 45 or 20)/ #Vgc
local Fhc,Ghc,Hhc,Ihc
for Jhc,Khc in ipairs(Vgc)do
local Lhc,Mhc,Nhc,Ohc=gb.bestTeam(Khc.info,Lgc,Dhc,Ehc)
local Phc=Xgc(Lhc,Khc)
if nhc(Phc,Ihc)then
Fhc,Ghc,Hhc,Ihc=Lhc,Mhc,Ohc,Phc
end
end
local Qhc=gb.sig(Fhc)==gb.sig(Lgc)
if Qhc then
Ihc=whc
end
if(Tgc.regen or 0)>0 then
local Rhc=false
for Shc,Thc in ipairs(Lgc)do
if V.bleeds(Thc.unit_id)then
Rhc=true
end
end
for Uhc,Vhc in ipairs(Fhc)do
if V.bleeds(Vhc.unit_id)then
Rhc=true
end
end
local Whc=not Rhc and V.bestBleeder(Lgc)or nil
if Whc then
local Xhc={}
for Yhc,Zhc in ipairs(Lgc)do
if not V.isFarm(Zhc.unit_id)and not V.allyBuff(Zhc.unit_id)then
local _hc=table.clone(Lgc)
_hc[Yhc]=Whc
local aic=Xgc(_hc,jhc(Ihc.style))
table.insert(Xhc,string.format(iee[3902],V.name(Zhc.unit_id),aic.wins))
if aic.score>Ihc.score then
Fhc,Ihc,Qhc=_hc,aic,false
Ghc={won=aic.wins>0,wave=aic.reach}
end
task.wait()
end
end
F.log(1,iee[3586],string.format(iee[3903],Fgc.d,V.name(Whc.unit_id),V.bleeds(Whc.unit_id)or 0,table.concat(Xhc,iee[2325])))
jb.bleedTried=string.format(iee[3904],V.name(Whc.unit_id),V.bleeds(Whc.unit_id)or 0,table.concat(Xhc,iee[2325]))
end
end
gb.memo=nil
local bic=Ihc.wins>whc.wins or(Ihc.wins==whc.wins and(Ihc.far or 0)>(whc.far or 0))
local cic=not Qhc and bic and Ihc.lostHere<=whc.lostHere
local dic,eic={},{}
for fic,gic in ipairs(Fhc)do
table.insert(dic,gic.uuid)
table.insert(eic,V.name(gic.unit_id))
end
P.simTeam.dg={uuids=dic,names=eic,won=Ghc.won,wave=Ghc.wave,better=cic,cur={won=Hhc.won,wave=Hhc.wave},at=os.time(),label=iee[3897],seed=tostring(Fgc.r._r),style=(cic and Ihc.style)or whc.style}
local function hic(iic)
return string.format(iee[3905],iic.wins,jb.WAY_WORDS[iic.style]or iee[873],math.floor(iic.reach+0.5),iic.w,iic.l)
end
pcall(function()
local jic={string.format(iee[3906],#Dhc)}
if jb.bleedTried then
table.insert(jic,jb.bleedTried)
end
jb.bleedTried=nil
local function kic(lic)
return string.format(iee[3907],lic.wins,3* #gb.LADDER,jb.WAY_WORDS[lic.style]or iee[873],lic.w,lic.l,(lic.lostHere or 0)>0 and string.format(iee[3908],lic.lostHere,(lic.left or 0)>0 and string.format(iee[3909],lic.left)or iee[873])or iee[873])
end
if Qhc and whc.wins>=3* #gb.LADDER then
table.insert(jic,string.format(iee[3910],gb.LADDER[#gb.LADDER],whc.w,whc.l))
elseif Qhc then
table.insert(jic,iee[3911]..kic(whc))
else
table.insert(jic,iee[3912]..kic(Ihc))
table.insert(jic,iee[3913]..kic(whc))
if cic then
table.insert(jic,iee[3914])
elseif not bic then
table.insert(jic,iee[3915])
else
table.insert(jic,string.format(iee[3916],Ihc.lostHere))
end
end
local mic,nic=pcall(jb.roomName,Fgc)
local oic=cic and Ihc or whc
gb.explainSave(iee[2661],string.format(iee[3899],Fgc.d,mic and tostring(nic)or iee[2185]),Tgc,cic and Fhc or Lgc,jic,cic,Lgc,{won=cic and Ghc.won or Hhc.won,wave=cic and Ghc.wave or Hhc.wave,total=Tgc.total,steps=oic.wins,mySteps=whc.wins,realW=oic.w,realL=oic.l})
end)
if not cic then
if Qhc and whc.wins>=3* #gb.LADDER then
F.log(1,iee[3586],string.format(iee[3917],Fgc.d,#Dhc,gb.LADDER[#gb.LADDER],whc.w,whc.l))
elseif Qhc then
F.log(1,iee[3586],string.format(iee[3918],Fgc.d,#Dhc,hic(whc)))
elseif not bic then
F.log(1,iee[3586],string.format(iee[3919],Fgc.d,hic(whc),table.concat(eic,iee[2062]),hic(Ihc)))
else
F.log(1,iee[3586],string.format(iee[3920],Fgc.d,hic(whc),table.concat(eic,iee[2062]),Ihc.lostHere,hic(Ihc)))
end
if Hgc and type(P.savedTeam)==iee[1950]and not ib.same(ib.team(),P.savedTeam)then
jb.startTeam(P.savedTeam,Fgc,iee[3901]..Fgc.d,true)
end
return
end
F.log(1,iee[3586],string.format(iee[3921],Fgc.d,table.concat(eic,iee[2062]),hic(Ihc),hic(whc)))
if Hgc then
if not ib.same(ib.team(),dic)then
jb.startTeam(dic,Fgc,iee[3922]..Fgc.d)
end
return
end
if O.autoTeam then
ab.equipTeam(dic,iee[3922]..Fgc.d)
task.wait(0.5)
else
F.log(1,iee[3586],iee[3923])
end
end
function jb.enter(pic,qic,ric)
for sic=1,5 do
local tic,uic=pcall(jb.act,pic)
if not tic then
F.log(1,iee[2336],iee[3924]..tostring(uic))
break
end
if uic==iee[3880]then
return false
end
if not uic then
break
end
task.wait(2)
pic=jb.data()
if not(pic and pic._started)then
return false
end
end
jb._pick=nil
local vic=jb.pick(pic)
if not vic then
jb.logState(pic,iee[3925])
local wic,xic,yic=jb.res(pic)
if xic+yic>0 then
F.log(1,iee[3840],string.format(iee[3926],xic,yic))
W.rec(iee[2661]).restUntil=os.time()+1800
return false
end
F.log(1,iee[3840],iee[3927])
F.request(iee[3856],iee[3857])
return false
end
local zic,Aic=pcall(jb.planTeam,vic,pic,ric)
if not zic then
F.log(1,iee[2336],iee[3928]..tostring(Aic))
end
if not ric then
local Bic=P.simTeam.dg
local Cic=tostring(vic.r._r)
P.dg.swapFail=type(P.dg.swapFail)==iee[1950]and P.dg.swapFail or{}
local Dic=tonumber(P.dg.swapFail[Cic])or 0
local Eic=jb.forced(vic)
local Fic=(Eic and Eic.uuids)or((Bic and Bic.better and Bic.seed==Cic and Dic<2)and Bic.uuids)or P.savedTeam
local Gic=ib.team()
local Hic= #Gic==6 and(not Fic or ib.same(Gic,Fic))
if not Hic then
P.dg.swapFail[Cic]=Dic+1
local Iic={}
for Jic,Kic in ipairs(V.equipped())do
table.insert(Iic,V.name(Kic.id))
end
if Dic+1>=2 and Bic and Bic.better and Bic.seed==Cic then
Bic.better=false
F.log(1,iee[2962],string.format(iee[3929],vic.d))
pcall(ab.restoreTeam)
end
F.log(1,iee[3840],string.format(iee[3930],vic.d,#Gic,table.concat(Iic,iee[2062])))
F.status(iee[2980],iee[3931]..vic.d)
W.rec(iee[2661]).restUntil=os.time()+45
P.pending=nil
F.saveSoon()
return false
end
P.dg.swapFail[Cic]=nil
local Lic,Mic=pcall(kb.relicsApply)
if not Lic then
F.log(1,iee[2336],iee[3326]..tostring(Mic))
end
end
if jb.lives(pic)<=1 then
P.dg.lost=P.dg.lost or{}
local Nic=jb.sim(vic)
local Oic=(P.dg.lost[tostring(vic.r._r)]or{})[W.teamSig()]or 0
local Pic= #V.equipped()<6
if(not Nic or Oic>=2 or Pic)and not(jb.playLast()and not Pic)then
local Qic=Pic and string.format(iee[3932],#V.equipped())or Oic>=2 and string.format(iee[3933],Oic)or iee[3934]
jb.note(string.format(iee[3935],vic.d,Qic))
W.rec(iee[2661]).restUntil=os.time()+3600
P.pending=nil
F.saveSoon()
return false
end
end
P.dg.room={seed=vic.r._r,d=vic.d}
P.pending={key=iee[2661],kind=iee[1970],level=iee[1970],diff=iee[2445],label=iee[3936]..vic.d,at=os.time(),value=qic,depth=vic.d}
if P.nextMode==iee[2661]then
P.nextMode=nil
end
local Ric,Sic,Tic=jb.res(pic)
local Uic=string.format(iee[3937],math.floor(vic.p*100+0.5),vic.sim and(iee[3938]..tostring(vic.sim.margin)..iee[2604])or iee[873],vic.nextRoom and jb.roomName(vic.nextRoom)or iee[3939],jb.lives(pic),Ric,Sic,Tic)
F.log(1,iee[2565],string.format(iee[3940],vic.d,jb.ROOMS,ric and iee[3941]or iee[873],jb.roomName(vic),Uic))
local Vic={}
for Wic,Xic in ipairs(jb._pick and jb._pick.rooms or{})do
if Xic~=vic then
table.insert(Vic,string.format(iee[3942],jb.roomName(Xic),math.floor((Xic.p or 0)*100+0.5),Xic.blocked and(iee[3943]..Xic.blocked..iee[2604])or iee[873]))
end
end
if#Vic>0 then
F.log(1,iee[3840],iee[3944]..table.concat(Vic,iee[2325]))
end
F.saveNow()
F.status(iee[2980],iee[3945]..vic.d)
local Yic=type(pic.selected_next)==iee[1950]and pic.selected_next.choice_str and tostring(pic.selected_next.choice_str)or nil
local Zic={tostring(vic.key)}
if Yic and Yic~=tostring(vic.key)and not ric then
table.insert(Zic,Yic)
end
for _ic,ajc in ipairs(Zic)do
if _ic==2 then
local bjc
for cjc,djc in ipairs(jb.rooms(pic))do
if tostring(djc.key)==ajc then
bjc=djc
end
end
F.log(1,iee[3840],string.format(iee[3946],ajc,bjc and jb.roomName(bjc)or iee[2185]))
end
local ejc,fjc=F.request(iee[3947],iee[3948],ajc)
local gjc=U.now()
while F.alive and U.now()-gjc<15 do
task.wait(1)
end
if not F.alive then
return true
end
F.log(1,iee[3840],string.format(iee[3949],ajc,tostring(fjc)))
end
jb.logState(pic,iee[3950])
P.pending=nil
if not ric then
W.rec(iee[2661]).restUntil=os.time()+900
end
F.saveSoon()
return false
end
function jb.chain()
task.wait(4)
local hjc=jb.data()
if not(hjc and hjc._started)then
return false
end
return jb.enter(hjc,O.dungeonValue,true)
end
jb.WAY_WORDS={fast=iee[3951],balanced=iee[3734],box=iee[3629]}
function jb.ways(ijc)
local function jjc(kjc,ljc,mjc)
local njc=table.clone(ijc)
njc.zone,njc.placeAll=ljc,mjc
return{style=kjc,info=njc}
end
local ojc=bb.forcedWay()
if ojc then
return{jjc(ojc,ojc==iee[3604],ojc==iee[3605]and iee[3350]or nil)}
end
local pjc={jjc(iee[3605],false,iee[3350]),jjc(iee[3643],false,nil)}
if O.killZone~=false then
table.insert(pjc,jjc(iee[3604],true,nil))
end
return pjc
end
jb.ROOM_K_MAX=6
function jb.roomK(qjc)
local rjc=qjc~=nil and type(P.dg.roomK)==iee[1950]and P.dg.roomK[tostring(qjc)]or nil
return type(rjc)==iee[1950]and tonumber(rjc.k)or 1
end
function jb.applyK(sjc,tjc)
local ujc=jb.roomK(tjc)
if sjc and ujc>1 then
sjc.hpScale=(tonumber(sjc.hpScale)or 1)*ujc
sjc.roomK=ujc
end
return ujc
end
function jb.roomLearn(vjc)
if vjc or bb.kind~=iee[1970]or bb.roomLearned then
return
end
local wjc=P.dg.room
local xjc,yjc=bb.pred,bb.calRun
if type(wjc)~=iee[1950]or wjc.seed==nil or type(xjc)~=iee[1950]or not xjc.won or type(yjc)~=iee[1950]then
return
end
local function zjc(Ajc,Bjc)
return type(Ajc)==iee[1950]and tonumber(Ajc[Bjc]or Ajc[tostring(Bjc)])or nil
end
local Cjc={}
for Djc=2,bb.wave()do
local Ejc,Fjc=zjc(yjc.alive,Djc),zjc(xjc.aliveAt,Djc)
if Ejc and Fjc and Ejc>0 and Fjc>0 then
table.insert(Cjc,Ejc/Fjc)
end
end
if#Cjc<3 then
return
end
table.sort(Cjc)
local Gjc=Cjc[math.ceil(#Cjc/2)]
bb.roomLearned=true
if Gjc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==iee[1950]and P.dg.roomK or{}
local Hjc=tostring(wjc.seed)
local Ijc=P.dg.roomK[Hjc]
local Jjc=math.min(jb.ROOM_K_MAX,jb.roomK(Hjc)*Gjc)
P.dg.roomK[Hjc]={k=Jjc,n=(type(Ijc)==iee[1950]and tonumber(Ijc.n)or 0)+1,at=os.time(),d=wjc.d}
bb.roomKUp=true
local Kjc={}
for Ljc,Mjc in pairs(P.dg.roomK)do
table.insert(Kjc,{s=Ljc,at=type(Mjc)==iee[1950]and tonumber(Mjc.at)or 0})
end
table.sort(Kjc,function(Njc,Ojc)
return Njc.at>Ojc.at
end)
for Pjc=31,#Kjc do
P.dg.roomK[Kjc[Pjc].s]=nil
end
F.log(1,iee[3840],string.format(iee[3952],tostring(wjc.d),Gjc,Jjc))
end
function jb.roomDone(Qjc)
pcall(jb.roomLearn,Qjc)
if type(P.simTeam)==iee[1950]and type(P.simTeam.dg)==iee[1950]then
P.simTeam.dg.stale=true
end
P.dg.playLast=nil
local Rjc=tonumber(type(bb.ld._dungeon)==iee[1950]and bb.ld._dungeon.depth)or(P.pending and tonumber(P.pending.depth))or 1
local Sjc=tostring(math.min(4,math.max(1,math.ceil(Rjc/5))))
local Tjc=P.dg.depth[Sjc]or{runs=0,wins=0}
Tjc.runs,Tjc.wins=(tonumber(Tjc.runs)or 0)+1,(tonumber(Tjc.wins)or 0)+(Qjc and 1 or 0)
P.dg.depth[Sjc]=Tjc
local Ujc=jb.data()
local Vjc,Wjc,Xjc=jb.res(Ujc)
jb.note(string.format(iee[3953],Rjc,jb.ROOMS,Qjc and iee[3954]or iee[2687],Vjc,Wjc,Xjc,jb.lives(Ujc)))
P.dg.teams=type(P.dg.teams)==iee[1950]and P.dg.teams or{}
local Yjc=P.dg.teams[W.teamSig()]or{w=0,l=0}
if Qjc then
Yjc.w=(tonumber(Yjc.w)or 0)+1
else
Yjc.l=(tonumber(Yjc.l)or 0)+1
end
P.dg.teams[W.teamSig()]=Yjc
if Qjc then
P.dg.lives=5
elseif P.dg.room and P.dg.room.d==Rjc then
P.dg.lost=P.dg.lost or{}
local Zjc,_jc=tostring(P.dg.room.seed),W.teamSig()
P.dg.lost[Zjc]=P.dg.lost[Zjc]or{}
P.dg.lost[Zjc][_jc]=(P.dg.lost[Zjc][_jc]or 0)+1
end
end
function jb.text()
if not O.dungeon then
return iee[2983]
end
local akc=jb.data()
if not akc then
return iee[3955]
end
if not akc._started then
return O.dungeonStart and iee[3956]or iee[3957]
end
local bkc,ckc,dkc=jb.res(akc)
