function bb.buildPath()
bb.samples={}
local qkc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not qkc then
return
end
for rkc,skc in pairs(qkc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[rkc.Name])then
local tkc={}
for ukc,vkc in ipairs(skc.points or{})do
table.insert(tkc,vkc.part.Position)
end
local wkc=0
for xkc=2,#tkc do
wkc=wkc+(tkc[xkc]-tkc[xkc-1]).Magnitude
end
local ykc=0
for zkc=2,#tkc do
local Akc,Bkc=tkc[zkc-1],tkc[zkc]
local Ckc=(Bkc-Akc).Magnitude
local Dkc=math.max(1,math.floor(Ckc/2))
for Ekc=0,Dkc-1 do
local Fkc=Akc:Lerp(Bkc,Ekc/Dkc)
table.insert(bb.samples,{pos=Fkc,prog=(ykc+Ckc*Ekc/Dkc)/math.max(1,wkc),lane=rkc.Name})
end
ykc=ykc+Ckc
end
if tkc[#tkc]then
table.insert(bb.samples,{pos=tkc[#tkc],prog=1,lane=rkc.Name})
end
end
end
pcall(bb.readHidden,qkc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Gkc=tonumber(bb.ld and bb.ld._portal_lanes)
local Hkc=gb.laneList(bb.samples)
if Gkc and Gkc>=1 and Hkc and#Hkc>Gkc then
bb.laneWant=Gkc
end
bb.laneTotal=Hkc and#Hkc or 1
bb.countLanes()
end
function bb.readHidden(Ikc)
local Jkc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Jkc)~=iee[1950]or not next(Jkc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Kkc
for Lkc,Mkc in pairs(Ikc)do
if Jkc[Lkc.Name]and type(Mkc.points)==iee[1950]and#Mkc.points>=2 then
local Nkc={}
for Okc,Pkc in ipairs(Mkc.points)do
Nkc[Okc]=U.flat(Pkc.part.Position)
end
local Qkc={}
for Rkc,Skc in ipairs(bb.samples)do
local Tkc=tostring(Skc.lane)
Qkc[Tkc]=Qkc[Tkc]or{}
table.insert(Qkc[Tkc],Skc)
end
local Ukc,Vkc
for Wkc,Xkc in pairs(Qkc)do
local Ykc=0
for Zkc=1,#Nkc,math.max(1,math.floor(#Nkc/20))do
local _kc=math.huge
for alc,blc in ipairs(Xkc)do
local clc=(U.flat(blc.pos)-Nkc[Zkc]).Magnitude
if clc<_kc then
_kc=clc
end
end
Ykc=Ykc+_kc
end
if not Vkc or Ykc<Vkc then
Ukc,Vkc=Wkc,Ykc
end
end
local dlc,elc,flc,glc,hlc,ilc={},nil,nil,nil,0,0
for jlc,klc in ipairs(Nkc)do
local llc,mlc=nil,math.huge
for nlc,olc in ipairs(Qkc[Ukc])do
local plc=(U.flat(olc.pos)-klc).Magnitude
if plc<mlc then
mlc,llc=plc,olc.prog
end
end
ilc=math.max(ilc,mlc)
if flc then
local qlc=llc-flc
local rlc=(qlc>0.002 and 1)or(qlc< -0.002 and-1)or glc
if glc and rlc and rlc~=glc then
table.insert(dlc,math.floor(flc*1000+0.5)/1000)
end
glc,hlc=rlc or glc,hlc+math.abs(qlc)
else
elc=llc
end
flc=llc
if jlc%50==0 then
task.wait()
end
end
if flc and ilc<=8 then
table.insert(dlc,math.floor(flc*1000+0.5)/1000)
Kkc=Kkc or{}
Kkc[Lkc.Name]={from=math.floor((elc or 0)*1000+0.5)/1000,len=math.floor(hlc*1000+0.5)/1000,turns=dlc,road=Ukc}
end
end
end
if not Kkc then
return
end
local slc=bb.ld.map
P.maps[slc]=P.maps[slc]or{}
local tlc=P.maps[slc].hidden
P.maps[slc].hidden=Kkc
if type(tlc)~=iee[1950]then
for ulc,vlc in pairs(Kkc)do
F.log(1,iee[2611],string.format(iee[3968],ulc,vlc.len,tostring(vlc.road),math.floor((#vlc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local wlc,xlc,ylc={},0,0
for zlc,Alc in ipairs(bb.samples)do
local Blc=tostring(Alc.lane)
if not wlc[Blc]then
xlc=xlc+1
end
wlc[Blc]=(wlc[Blc]or 0)+1
ylc=ylc+1
end
bb.laneCount={n=xlc,by=wlc,avg=xlc>0 and ylc/xlc or 1}
if xlc>=2 then
local Clc,Dlc=pcall(gb.laneSep,bb.samples)
local Elc=P.maps[bb.mapKey()]
if Clc and Dlc and type(Elc)==iee[1950]then
Elc.sep=Dlc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local Flc,Glc={},0
for Hlc,Ilc in ipairs(workspace._UNITS:GetChildren())do
local Jlc=Ilc:FindFirstChild(iee[2013])
if Jlc and Jlc:FindFirstChild(iee[3969])and Jlc.player.Value==nil and Jlc:FindFirstChild(iee[3970])and Ilc:FindFirstChild(iee[3170])then
local Klc=tostring(Jlc.lane.Value)
if not Flc[Klc]then
Flc[Klc]=true
Glc=Glc+1
end
end
end
if Glc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,iee[2611],iee[3971])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if Glc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local Llc,Mlc={},{}
for Nlc,Olc in ipairs(bb.samples)do
if Flc[tostring(Olc.lane)]then
table.insert(Llc,Olc)
end
end
if#Llc==0 then
bb.laneWant=nil
return true
end
for Plc in pairs(Flc)do
table.insert(Mlc,Plc)
end
table.sort(Mlc)
bb.samples,bb.laneCut=Llc,table.concat(Mlc,iee[2264])
bb.countLanes()
local Qlc,Rlc=pcall(bb.buildCandidates)
if not Qlc then
F.log(1,iee[2336],iee[3972]..tostring(Rlc))
end
F.log(1,iee[2611],string.format(iee[3973],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local Slc,Tlc=pcall(bb.planSpots)
bb.planning=nil
if not Slc then
