function bb.infStop(gmc)
local hmc=0
for imc,jmc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
hmc=math.max(hmc,tonumber(jmc.wave)or 0)
end
if hmc<=0 or gmc<=hmc+1 then
return
end
local kmc=P.train.on
if bb.trainee and kmc and kmc.have+(kmc.got or 0)+(bb.trainTk or 0)<kmc.need then
return
end
if not ab.every(iee[3980],60)then
return
end
local lmc=W.rec(bb.key)
local mmc=tonumber(lmc.timed)or 0
local nmc=W.INF_PAY
local omc
if gmc>=(nmc.cap+nmc.less)/nmc.per then
omc=0
else
local pmc=bb.infWaveAt or{}
local qmc,rmc=pmc[gmc],pmc[gmc-5]
if qmc and rmc and qmc>rmc then
omc=nmc.per*5/((qmc-rmc)/60)
end
if not omc then
omc=(mmc>0 and(lmc.sec or 0)>0)and math.max(0.5,(lmc.gems or 0)/(lmc.sec/60))or 2.5
end
end
local smc=pcall(W.pick)
local tmc
for umc,vmc in ipairs(smc and W.lastScored or{})do
if vmc.kind~=iee[1969]and(not tmc or(vmc.score or 0)>(tmc.score or 0))then
tmc=vmc
end
end
if not tmc or(tmc.score or 0)<=omc then
return
end
bb.stopping=true
F.log(1,iee[2611],string.format(iee[3981],gmc,omc,tmc.score,tmc.label))
bb.sellAll()
end
function bb.trainLeave(wmc)
