end
local zmc,Amc,Bmc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if zmc and(Amc or 0)>0 and Bmc>0 and wmc<=Bmc then
F.status(iee[3134],string.format(iee[3982],V.name(xmc.id),xmc.what,Bmc))
return
end
bb.stopping=true
F.log(1,iee[2611],string.format(iee[3983],V.name(xmc.id),xmc.what,U.fmt(ymc),U.fmt(xmc.need),wmc))
bb.sellAll()
