Voc=Voc.Unit
local Woc=Vector3 .new(-Voc.Z,0,Voc.X)
for Xoc,Yoc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Zoc,_oc in ipairs({1,-1})do
local apc=Toc.pos+Woc*Yoc*_oc
local bpc=string.format(iee[4001],math.floor(apc.X/1.5),math.floor(apc.Z/1.5))
