function bb.coverage(cpc,dpc)
local epc={}
for fpc,gpc in ipairs(cpc)do
local hpc=gpc._stats
if not V.isFarm(hpc.id.Value)and hpc:FindFirstChild(iee[2202])then
table.insert(epc,{p=U.flat(gpc:GetPivot().Position),r=hpc.range.Value*(V.SUMMONER[hpc.id.Value]and V.SUMMONER[hpc.id.Value].reach or 1),air=bb.canAir(gpc)})
end
end
local ipc,jpc=0,0
if#epc>0 then
for kpc,lpc in ipairs(bb.samples)do
if lpc.prog>jpc then
local mpc=U.flat(lpc.pos)
for npc,opc in ipairs(epc)do
if(mpc-opc.p).Magnitude<=opc.r then
if lpc.prog>ipc then
ipc=lpc.prog
end
if opc.air then
jpc=lpc.prog
break
end
end
end
end
end
end
local ppc,qpc={},bb.laneCount
if qpc and qpc.n>=2 and#epc>0 then
local rpc={}
for spc,tpc in ipairs(bb.samples)do
local upc=U.flat(tpc.pos)
for vpc,wpc in ipairs(epc)do
if(upc-wpc.p).Magnitude<=wpc.r then
local xpc=tostring(tpc.lane)
rpc[xpc]=(rpc[xpc]or 0)+1
if tpc.prog>(ppc[xpc]or 0)then
ppc[xpc]=tpc.prog
end
break
end
end
end
local ypc,zpc={},0
for Apc,Bpc in pairs(qpc.by)do
ypc[Apc]=(rpc[Apc]or 0)/math.max(1,Bpc)
zpc=math.max(zpc,ypc[Apc])
end
bb.laneW={}
for Cpc,Dpc in pairs(qpc.by)do
bb.laneW[Cpc]=(qpc.avg/math.max(1,Dpc))*(1+1.5*(zpc>0 and(1-ypc[Cpc]/zpc)or 0))
end
bb.laneFrac=ypc
else
bb.laneW,bb.laneFrac=nil,nil
end
local Epc,Fpc,Gpc
if#epc>0 then
for Hpc,Ipc in ipairs(dpc)do
local Jpc=(bb.laneW and Ipc.lane)and(ppc[tostring(Ipc.lane)]or 0)or ipc
if Ipc.hp>0 and Ipc.prog>Jpc+0.02 and Ipc.prog>(Epc or 0)then
Epc,Gpc=Ipc.prog,bb.laneW and Ipc.lane or nil
end
if Ipc.hp>0 and Ipc.fly and Ipc.prog>jpc+0.02 then
Fpc=true
end
end
end
local Kpc= #epc>0 and(bb.pressure or 0)>=ipc-0.08
return{covEnd=ipc,airEnd=jpc,leak=Epc,leakLane=Gpc,covL=ppc,airLeak=Fpc,push=Kpc,units= #epc}
end
