return type(ZCc)==iee[1950]and ZCc or{}
end
function bb.nearSpot(_Cc,aDc,bDc)
local cDc,dDc=nil,9
for eDc,fDc in ipairs(_Cc or{})do
local gDc=(fDc.X-aDc)^2+(fDc.Z-bDc)^2
if gDc<=dDc then
cDc,dDc=fDc,gDc
end
end
return cDc
end
function bb.baseRange(hDc)
local iDc=V.rows(hDc)
local jDc=iDc and iDc[iDc.max]and tonumber(iDc[iDc.max].range)
return jDc or(N.Units[hDc]and tonumber(N.Units[hDc].range))or nil
end
function bb.studyMoves(kDc,lDc)
local mDc=V.rows(kDc.id)
local nDc=V.range(kDc.e.u,mDc.max)*lDc
local oDc=nDc*nDc
local pDc,qDc={},{}
local rDc,sDc=bb.hurtSamples(),bb.sandLine()
for tDc,uDc in ipairs(kDc.spots or{})do
local vDc,wDc,xDc,yDc,zDc=0,0,0,0,0
for ADc,BDc in ipairs(rDc)do
local CDc,DDc=BDc.pos.X-uDc.X,BDc.pos.Z-uDc.Z
if CDc*CDc+DDc*DDc<=oDc then
xDc=xDc+1
local EDc=math.min(49,math.floor(BDc.prog*50))
if EDc<25 then
vDc=bit32 .bor(vDc,bit32 .lshift(1,EDc))
else
wDc=bit32 .bor(wDc,bit32 .lshift(1,EDc-25))
end
if BDc.prog-sDc<=0.3 then
yDc=yDc+1
elseif BDc.prog>=0.7 then
zDc=zDc+1
end
end
end
if xDc>0 then
local FDc=vDc..iee[2085]..wDc
local GDc=pDc[FDc]
if not GDc then
GDc={p=uDc,lo=vDc,hi=wDc,n=xDc,early=yDc,late=zDc}
pDc[FDc]=GDc
table.insert(qDc,GDc)
elseif xDc>GDc.n then
GDc.p,GDc.n,GDc.early,GDc.late=uDc,xDc,yDc,zDc
end
end
if tDc%40==0 then
task.wait()
end
end
local HDc={}
for IDc,JDc in ipairs(qDc)do
local KDc=false
for LDc,MDc in ipairs(qDc)do
if IDc~=LDc and MDc.n>=JDc.n and bit32 .band(JDc.lo,MDc.lo)==JDc.lo and bit32 .band(JDc.hi,MDc.hi)==JDc.hi and(MDc.lo~=JDc.lo or MDc.hi~=JDc.hi or MDc.n>JDc.n)then
KDc=true
break
end
end
if not KDc then
table.insert(HDc,JDc)
end
if IDc%40==0 then
task.wait()
end
end
local NDc,ODc={},{}
local function PDc(QDc)
if QDc and not ODc[QDc]then
ODc[QDc]=true
table.insert(NDc,QDc)
end
end
table.sort(HDc,function(RDc,SDc)
return RDc.n>SDc.n
end)
for TDc=1,math.min(bb.STUDY_K,#HDc)do
PDc(HDc[TDc].p)
end
table.sort(HDc,function(UDc,VDc)
return UDc.early>VDc.early
end)
PDc(HDc[1]and HDc[1].p)
PDc(HDc[2]and HDc[2].p)
table.sort(HDc,function(WDc,XDc)
return WDc.late>XDc.late
end)
PDc(HDc[1]and HDc[1].p)
PDc(HDc[2]and HDc[2].p)
local YDc=0
for ZDc,_Dc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if YDc>=bb.STUDY_SHARED then
break
end
local aEc=false
for bEc,cEc in ipairs(type(_Dc.units)==iee[1950]and _Dc.units or{})do
local dEc=cEc==kDc.id and nDc or((bb.baseRange(cEc)or 0)*lDc)
if cEc==kDc.id or(dEc>0 and math.abs(dEc-nDc)<=0.3*nDc)then
aEc=true
break
end
end
local eEc=aEc and tonumber(_Dc.x)and tonumber(_Dc.z)and bb.nearSpot(kDc.spots,tonumber(_Dc.x),tonumber(_Dc.z))or nil
if eEc and not ODc[eEc]then
PDc(eEc)
YDc=YDc+1
end
end
return NDc,#qDc,#HDc,YDc
end
function bb.studyRun(fEc)
local gEc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-gEc<20)do
task.wait(1)
end
local function hEc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and F.where==iee[2022]
end
if not hEc()then
return
end
local iEc,jEc,kEc=fEc.info,fEc.team,fEc.base
local lEc=iEc.timeLimit~=nil
local mEc=lEc and 1 or math.max(1,tonumber(fEc.hard)or 1)
local nEc={mEc*0.95,mEc*1.05}
local oEc=bb.bookFor(iEc)
local pEc={key=fEc.key,label=bb.label(),n=oEc and tonumber(oEc.n)or 0,run=0,timed=lEc,kills=iEc.killScore and true or nil,hp=mEc,at=os.time()}
bb.study=pEc
local qEc,rEc,sEc,tEc,uEc={},0,0,0,0
for vEc,wEc in ipairs(fEc.attackers)do
local xEc,yEc,zEc,AEc=bb.studyMoves(wEc,fEc.scale)
qEc[wEc.id]=xEc
rEc,sEc,tEc,uEc=rEc+ #(wEc.spots or{}),sEc+yEc,tEc+ #xEc,uEc+AEc
if not hEc()then
return
end
end
pEc.moves=tEc
F.log(1,iee[2695],string.format(iee[4138],pEc.label,rEc,sEc,tEc,uEc>0 and string.format(iee[4139],uEc)or iee[873]))
local BEc={}
local function CEc(DEc)
return{samples=bb.samples,cache=BEc,spots=DEc,style=kEc.style,list=kEc.list,hybridHill=kEc.hybridHill}
end
local function EEc(FEc)
local GEc=0
for HEc,IEc in pairs(FEc)do
local JEc=bb.spotRec(HEc,IEc)
if JEc then
GEc=GEc+(tonumber(JEc.wins)or 0)*200-((tonumber(JEc.runs)or 0)-(tonumber(JEc.wins)or 0))*1500
end
end
return GEc
end
local function KEc(LEc)
local MEc,NEc,OEc=0,0,0
for PEc,QEc in ipairs(nEc)do
local REc=os.clock()
local SEc=gb.runRaw(iEc,jEc,{hpMul=QEc,layout=CEc(LEc),bg=true})
MEc,NEc,OEc=MEc+gb.objective(SEc),NEc+(tonumber(SEc.kills)or 0),OEc+(tonumber(SEc.wave)or 0)
task.wait(math.clamp((os.clock()-REc)*3,0.25,fEc.pauseMax or 1.5))
if not hEc()then
return nil
end
end
pEc.n,pEc.run=pEc.n+1,pEc.run+1
return MEc/ #nEc*100+EEc(LEc),NEc/ #nEc,OEc/ #nEc
end
local function TEc(UEc)
local VEc={}
for WEc,XEc in pairs(UEc)do
VEc[WEc]=XEc
end
return VEc
end
local function YEc(ZEc,_Ec,aFc)
for bFc,cFc in pairs(ZEc)do
if bFc~=_Ec and(U.flat(cFc)-U.flat(aFc)).Magnitude<4.5 then
return true
end
end
return false
end
local dFc={spots=TEc(kEc.spots)}
dFc.s,dFc.kills,dFc.wave=KEc(dFc.spots)
if not dFc.s then
return bb.studyEnd(pEc,fEc,nil)
end
pEc.baseKills,pEc.baseWave=dFc.kills,dFc.wave
pEc.bestKills,pEc.bestWave=dFc.kills,dFc.wave
if oEc and oEc.aside==nil then
local eFc,fFc=TEc(dFc.spots),0
for gFc,hFc in ipairs(fEc.attackers)do
local iFc=oEc.spots[hFc.id]
local jFc=type(iFc)==iee[1950]and tonumber(iFc[1])and tonumber(iFc[3])and bb.nearSpot(hFc.spots,tonumber(iFc[1]),tonumber(iFc[3]))or nil
if jFc and jFc~=eFc[hFc.id]and not YEc(eFc,hFc.id,jFc)then
eFc[hFc.id]=jFc
fFc=fFc+1
end
end
if fFc>0 then
local kFc,lFc,mFc=KEc(eFc)
if not kFc then
return bb.studyEnd(pEc,fEc,dFc)
end
if kFc>dFc.s then
dFc={spots=eFc,s=kFc,kills=lFc,wave=mFc}
pEc.bestKills,pEc.bestWave=lFc,mFc
end
end
end
local nFc,oFc=U.now(),pEc.run
local function pFc(qFc)
if not(qFc.s and qFc.s>dFc.s+math.max(50,math.abs(dFc.s)*0.005))then
return false
end
dFc=qFc
pEc.bestKills,pEc.bestWave,pEc.better=qFc.kills,qFc.wave,(pEc.better or 0)+1
pcall(bb.bookSave,iEc,fEc,dFc,pEc)
return true
end
local function rFc()
if pEc.run-oFc>=60 or U.now()-nFc>240 then
nFc,oFc=U.now(),pEc.run
F.log(1,iee[2695],bb.studyWords(pEc))
end
end
local sFc={dFc}
for tFc,uFc in ipairs(fEc.attackers)do
local vFc={}
for wFc,xFc in ipairs(sFc)do
table.insert(vFc,xFc)
for yFc,zFc in ipairs(qEc[uFc.id]or{})do
if zFc~=xFc.spots[uFc.id]and not YEc(xFc.spots,uFc.id,zFc)then
local AFc=TEc(xFc.spots)
AFc[uFc.id]=zFc
local BFc,CFc,DFc=KEc(AFc)
if not BFc then
return bb.studyEnd(pEc,fEc,dFc)
end
local EFc={spots=AFc,s=BFc,kills=CFc,wave=DFc}
table.insert(vFc,EFc)
pFc(EFc)
rFc()
end
end
end
table.sort(vFc,function(FFc,GFc)
return(FFc.s or-1e18)>(GFc.s or-1e18)
end)
sFc={}
for HFc=1,math.min(bb.STUDY_BEAM,#vFc)do
table.insert(sFc,vFc[HFc])
end
end
local IFc={}
for JFc,KFc in ipairs(fEc.attackers)do
if qEc[KFc.id]and#qEc[KFc.id]>0 then
table.insert(IFc,KFc.id)
end
end
while hEc()and#IFc>0 do
local LFc=TEc(dFc.spots)
for MFc=1,math.min(2,#IFc)do
local NFc=IFc[math.random(#IFc)]
local OFc=qEc[NFc]
local PFc=OFc[math.random(#OFc)]
if not YEc(LFc,NFc,PFc)then
LFc[NFc]=PFc
end
end
local QFc,RFc,SFc=KEc(LFc)
if not QFc then
break
end
pFc({spots=LFc,s=QFc,kills=RFc,wave=SFc})
rFc()
end
bb.studyEnd(pEc,fEc,dFc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(TFc,UFc)
local VFc=N.PC.raycast(TFc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not VFc then
return nil
end
if not N.PC.is_valid_raycast_hit(VFc.Instance,UFc)then
return nil
end
local WFc=VFc.Position
if bb.blockedSpot(WFc)then
return nil
end
local XFc=(tonumber(UFc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(XFc*2,2.5,XFc*2)
bb.probe.CFrame=CFrame.new(WFc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return WFc
end
function bb.studyInfinite()
if O.mapStudy==false or not(bb.info and bb.infinite)or bb.kind==iee[2403]then
return
end
local YFc=bb.info
local function ZFc()
return not F.alive or bb.finished or bb.result or F.where~=iee[2022]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local _Fc,aGc={},{}
for bGc,cGc in ipairs(bb.team or{})do
table.insert(_Fc,cGc.u)
if not V.isFarm(cGc.id)and not V.allyBuff(cGc.id)and cGc.uuid~=bb.trainee and V.rows(cGc.id)then
local dGc,eGc=pcall(V.score,cGc.u,bb.mod)
table.insert(aGc,{e=cGc,id=cGc.id,sc=dGc and eGc or 0})
end
end
if#aGc==0 then
return
end
table.sort(aGc,function(fGc,gGc)
return fGc.sc>gGc.sc
end)
local function hGc()
local iGc,jGc={},0
for kGc,lGc in ipairs(aGc)do
for mGc,nGc in ipairs(bb.mine or{})do
local oGc=nGc:FindFirstChild(iee[2013])
local pGc=oGc and oGc:FindFirstChild(iee[2326])
if pGc and pGc.Value==lGc.e.uuid and oGc:FindFirstChild(iee[2327])and oGc.id.Value==lGc.id then
iGc[lGc.id]=nGc:GetPivot().Position
jGc=jGc+1
break
end
end
end
return iGc,jGc
end
