if GMc and HMc then
if FMc and FMc>=(tonumber(P.caps[zMc.uuid])or math.huge)then
F.log(1,iee[4008],string.format(iee[4165],V.name(zMc.id),tostring(P.caps[zMc.uuid])))
P.caps[zMc.uuid],P.capsAt[zMc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(zMc.data.cost or 0)
table.insert(bb.actions,string.format(iee[4166],V.name(zMc.id)))
F.log(1,iee[4008],string.format(iee[4167],V.name(zMc.id),bb.spotKey(CMc),DMc,AMc))
