table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=zMc.id,x=math.floor(CMc.X),z=math.floor(CMc.Z),cover=math.floor((DMc or 0)+0.5),why=tostring(AMc):sub(1,90)})
F.status(iee[4071],string.format(iee[4168],V.name(zMc.id),AMc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[zMc.uuid]=(bb.placedAt[zMc.uuid]or 0)+1
return true
end
if EMc>=(zMc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[zMc.uuid]=(bb.placeFail[zMc.uuid]or 0)+1
if bb.placeFail[zMc.uuid]>=2 then
bb.noSpot[zMc.uuid]=3
F.log(1,iee[4008],string.format(iee[4169],V.name(zMc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if GMc and EMc>=(zMc.data.cost or 0)and not bb.random then
local IMc=bb.spotKey(CMc)
bb.refused[IMc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[zMc.uuid]=(bb.unitRefusals[zMc.uuid]or 0)+1
if not bb.crowded()then
