P.blocked[JMc]=P.blocked[JMc]or{}
if not bb.refusedRun[IMc]then
P.blocked[JMc][IMc]=(tonumber(P.blocked[JMc][IMc])or 0)+1
bb.refusedRun[IMc]=true
P.blockedAt[JMc]=P.blockedAt[JMc]or{}
P.blockedAt[JMc][IMc]=os.time()
end
if bb.unitRefusals[zMc.uuid]>=3 then
local KMc=math.max(1,bb.count(zMc.uuid))
if P.caps[zMc.uuid]~=KMc or not V.learnedCap(zMc.uuid)then
P.caps[zMc.uuid],P.capsAt[zMc.uuid]=KMc,os.time()
F.log(1,iee[4008],string.format(iee[4170],V.name(zMc.id),KMc))
end
end
elseif bb.unitRefusals[zMc.uuid]>=3 and(bb.noSpot[zMc.uuid]or 0)<3 then
bb.noSpot[zMc.uuid]=3
F.log(1,iee[4008],string.format(iee[4171],V.name(zMc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,iee[4008],string.format(iee[4172],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,iee[4008],iee[4173]..IMc..iee[2859]..V.name(zMc.id))
F.saveSoon()
end
return false
end
