end
local zOc=U.flat(oOc)
for AOc,BOc in ipairs(bb.samples)do
if(U.flat(BOc.pos)-zOc).Magnitude<=nOc then
local COc=math.min(gb.BINS,math.floor(BOc.prog*gb.BINS)+1)
tOc[COc]=iee[2389]
if uOc[tostring(BOc.lane)]then
uOc[tostring(BOc.lane)][COc]=iee[2389]
end
end
