end
end
end
task.wait()
end
local FOc=P.maps[bOc]or{}
P.maps[bOc]={v=1,laneV=1,bins=kOc,binsL=mOc and lOc or nil,lanes=mOc,hill=gOc,spots= #fOc,dens=FOc.dens,densN=FOc.densN,binsDensN=FOc.densN or 0,lay=FOc.lay,walk=FOc.walk,walkN=FOc.walkN,sep=mOc and(select(2,pcall(gb.laneSep,bb.samples))or FOc.sep)or nil,hidden=FOc.hidden}
gb._masks={}
