if oRc and((oRc.stun or 0)>0 or(oRc.slowTime or 0)>0)then
iRc=iRc+1
end
end
local pRc,qRc=gb.mask(bb.info.map,V.range(fRc.u,0)*(bb.info.rangeScale or 1)),0
for rRc=1,gb.BINS do
