function bb.buffGain(uRc)
local vRc=V.allyBuff(uRc.id)
if not vRc then
return 0
end
local wRc=bb.buffShort(vRc)
local xRc=P.stack[vRc.attack]
local yRc=xRc and xRc.stacks and(xRc.cap or 1)or nil
local zRc,ARc=pcall(V.range,uRc.u,0)
ARc=(zRc and tonumber(ARc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local BRc=yRc and O.community and tonumber(vRc.time)and tonumber(vRc.cd)
local function CRc(DRc,ERc)
local FRc=math.floor(DRc*vRc.time/math.max(1,vRc.cd)+0.001)
return math.min(yRc,(1+ERc)^FRc-1)
end
local GRc=0
for HRc,IRc in ipairs(wRc)do
local JRc=0
for KRc,LRc in ipairs(wRc)do
if(LRc.pos-IRc.pos).Magnitude<=ARc then
local MRc=vRc.types[LRc.base]
local NRc=MRc*vRc.uptime
if BRc then
local ORc,PRc=CRc(LRc.n,MRc),LRc.n+1
while PRc<LRc.n+6 and CRc(PRc,MRc)<=ORc+0.001 do
PRc=PRc+1
end
NRc=math.max(0,(CRc(PRc,MRc)-ORc)/(PRc-LRc.n))
elseif yRc then
NRc=math.max(0,math.min(yRc,(LRc.n+1)*MRc*vRc.uptime)-math.min(yRc,LRc.n*MRc*vRc.uptime))
end
JRc=JRc+LRc.dps*NRc
end
end
GRc=math.max(GRc,JRc)
end
return GRc*(BRc and 1 or 0.7)
end
