end
end
for s0c,t0c in pairs(bb.helperDealt or{})do
if t0c.owner and V.SUMMONER[t0c.owner]and not V.droneHelper(t0c)then
p0c[t0c.owner]=(p0c[t0c.owner]or 0)+(tonumber(t0c.v)or 0)
end
end
