v0c,w0c=v0c+(p0c[y0c]or 0),w0c+z0c
local A0c=tonumber(u0c[y0c])or z0c
if A0c>0 then
table.insert(x0c,{id=y0c,r=(p0c[y0c]or 0)/A0c,w=A0c})
end
end
end
if v0c<=0 or w0c<=0 then
return
end
table.sort(x0c,function(B0c,C0c)
return B0c.r<C0c.r
end)
local function D0c(E0c)
local F0c,G0c=0,0
for H0c,I0c in ipairs(x0c)do
if I0c.id~=E0c then
F0c=F0c+I0c.w
end
end
if F0c<=0 then
