O0c.eff=O0c.eff+(Q0c-O0c.eff)*P0c
O0c.n=O0c.n+1
P.learn[L0c]=O0c
end
end
local R0c=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if R0c and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==iee[1950]and P.mapLearn or{}
