V0c.eff,V0c.v=(tonumber(V0c.eff)or U0c)*(V.sumRescale(T0c)or 1),5
end
if(tonumber(V0c.v)or 0)<6 then
V0c.eff,V0c.v=(tonumber(V0c.eff)or U0c)*(1-(V.SUMMONER[T0c]and V.SUMMONER[T0c].droneShare or 0)),6
end
local W0c=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(V0c.n)or 0))))
