V0c.n=(tonumber(V0c.n)or 0)+1
S0c[T0c]=V0c
end
S0c._at=os.time()
P.mapLearn[R0c]=S0c
if U.count(P.mapLearn)>80 then
local X0c,Y0c
for Z0c,_0c in pairs(P.mapLearn)do
if not Y0c or(tonumber(_0c._at)or 0)<Y0c then
