function nb.K.setFocus(EMd)
local FMd=nb.K
FMd.cur=EMd
if not FMd.ring then
FMd.ring=Instance.new(iee[5032])
FMd.ring.Name=iee[5181]
FMd.ring.Thickness=2
FMd.ring.Color=Color3 .new(1,1,1)
FMd.ring.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
end
if not EMd then
FMd.ring.Parent=nil
return
end
FMd.ring.Parent=EMd.ring or EMd.obj
local GMd=EMd.obj:FindFirstAncestorWhichIsA(iee[5098])
if GMd then
local HMd=EMd.obj.AbsolutePosition.Y-GMd.AbsolutePosition.Y
local IMd,JMd=EMd.obj.AbsoluteSize.Y,GMd.AbsoluteWindowSize.Y
if HMd<0 then
GMd.CanvasPosition=Vector2 .new(0,math.max(0,GMd.CanvasPosition.Y+HMd-10))
elseif HMd+IMd>JMd then
GMd.CanvasPosition=Vector2 .new(0,GMd.CanvasPosition.Y+HMd+IMd-JMd+10)
end
end
end
function nb.K.key(KMd,LMd)
local MMd,NMd,OMd=nb.K,nb.Win,Enum.KeyCode
if MMd.cur and not(MMd.cur.obj and MMd.cur.obj.Parent and MMd.shown(MMd.cur.obj))then
MMd.setFocus(nil)
end
if MMd.cur and MMd.cur.listKey and MMd.cur.listKey(KMd)then
return true
end
if KMd==OMd.PageUp or KMd==OMd.PageDown then
local PMd={}
for QMd,RMd in pairs(NMd._tabs)do
table.insert(PMd,{name=QMd,y=RMd.btn.AbsolutePosition.Y,on=RMd.page.Visible})
end
table.sort(PMd,function(SMd,TMd)
return SMd.y<TMd.y
end)
local UMd=1
for VMd,WMd in ipairs(PMd)do
if WMd.on then
UMd=VMd
end
end
UMd=(UMd-1+(KMd==OMd.PageDown and 1 or-1))% #PMd+1
MMd.setFocus(nil)
NMd:SelectTab(PMd[UMd].name)
return true
end
if KMd==OMd.Tab or KMd==OMd.Down or KMd==OMd.Up then
local XMd=MMd.order()
if#XMd==0 then
return true
end
local YMd=KMd==OMd.Up or(KMd==OMd.Tab and LMd)
local ZMd=table.find(XMd,MMd.cur)
if not ZMd then
ZMd=YMd and#XMd or 1
else
ZMd=(ZMd-1+(YMd and-1 or 1))% #XMd+1
end
MMd.setFocus(XMd[ZMd])
return true
end
if not MMd.cur then
return false
end
if KMd==OMd.Return or KMd==OMd.KeypadEnter or KMd==OMd.Space then
if MMd.cur.activate then
MMd.cur.activate()
end
return true
end
if KMd==OMd.Left or KMd==OMd.Right then
if MMd.cur.adjust then
MMd.cur.adjust(KMd==OMd.Right and 1 or-1)
end
return true
end
if KMd==OMd.Escape then
MMd.setFocus(nil)
return true
end
return false
end
function nb.K.keys(_Md)
local aNd=nb.K
local bNd,cNd,dNd=game:GetService(iee[5182]),game:GetService(iee[5106]),game:GetService(iee[5183])
local eNd=Enum.KeyCode
aNd.keyName=iee[5184]..(tostring(nb.TITLE):gsub(iee[5185],iee[873]))
function aNd.over()
local fNd=_Md._main
if not(fNd and fNd.Parent and fNd.Visible)then
return false
end
local gNd=cNd:GetMouseLocation()
local hNd=dNd:GetGuiInset()
local iNd,jNd=gNd.X,gNd.Y-hNd.Y
local kNd,lNd=fNd.AbsolutePosition,fNd.AbsoluteSize
return iNd>=kNd.X and iNd<=kNd.X+lNd.X and jNd>=kNd.Y and jNd<=kNd.Y+lNd.Y
end
bNd:BindActionAtPriority(aNd.keyName,function(mNd,nNd,oNd)
if nNd~=Enum.UserInputState.Begin then
return Enum.ContextActionResult.Pass
end
if cNd:GetFocusedTextBox()or not aNd.over()then
return Enum.ContextActionResult.Pass
end
local pNd,qNd=pcall(aNd.key,oNd.KeyCode,cNd:IsKeyDown(eNd.LeftShift)or cNd:IsKeyDown(eNd.RightShift))
return(pNd and qNd)and Enum.ContextActionResult.Sink or Enum.ContextActionResult.Pass
end,false,3000,eNd.Tab,eNd.Return,eNd.KeypadEnter,eNd.Space,eNd.Left,eNd.Right,eNd.Up,eNd.Down,eNd.Escape,eNd.PageUp,eNd.PageDown)
_Md._track(cNd.InputBegan:Connect(function(rNd)
if rNd.UserInputType==Enum.UserInputType.MouseButton1 and aNd.cur then
pcall(aNd.setFocus,nil)
end
end))
_Md._screen.Destroying:Connect(function()
pcall(function()
bNd:UnbindAction(aNd.keyName)
end)
end)
end
